// Generated by `just generate` from `src/plugins/dotclaude/slices/asks/domain/lintdiff.ts`. Edit the source and run `just generate`.
// The check on a weaker lint config, runner config, or `tsconfig.json` (package P36), as pure functions.
// A change gets no ask only when every changed part is safe:
// a change of format or comments only, a move with the same content (keys of a map in any order),
// an added key whose value is the strictest level (`error`, `true` for a strict flag, a number for a threshold),
// an added entry in a list of rules or files, a raised level, a raised threshold, or a strict flag that goes to `true`.
// Every other change asks: a removed key, a lowered value, a new `off`, `warn`, or `false`,
// a new ignore, exclude, or `!` pattern, a narrowed list, and a new key that is not on the safe list.
// A format that the code cannot read asks. The check on a CI file is in `cidiff.ts`.

import {
  CODE_CONFIG_FILE,
  GROWABLE_LIST_KEY,
  IGNORE_KEY,
  INI_CONFIG_FILE,
  LEVEL_RANK,
  NEGATED_ENTRY,
  PYPROJECT_SECTIONS,
  SETUP_CFG_SECTIONS,
  STRICT_FLAG_KEY,
  THRESHOLD_KEY,
} from "../limits.ts";
import { type Conf, jsonConf, sectionConf } from "./confmap.ts";
import { UNREADABLE } from "./jsondiff.ts";
import { shown } from "./shown.ts";
import { codeWeaker } from "./tokendiff.ts";
import { yamlConf } from "./yamlmap.ts";

const keyOf = (path: string): string => path.split(".").at(-1) as string;

const number = (text: string): number | undefined =>
  /^-?\d+(?:\.\d+)?$/.test(text) ? Number(text) : undefined;

const level = (text: string): number | undefined =>
  LEVEL_RANK[text.toLowerCase()];

/** True when the value of a key that was `was` is as strict or stricter as `now`, for a scalar that changed. */
const stricter = (path: string, was: string, now: string): boolean => {
  const [a, b] = [number(was), number(now)];
  if (a !== undefined && b !== undefined)
    return (
      b > a &&
      (path.split(".").some((p) => THRESHOLD_KEY.test(p)) ||
        (path.split(".").includes("rules") && a >= 0 && b <= 2))
    );
  const [x, y] = [level(was), level(now)];
  if (x !== undefined && y !== undefined) return y > x;
  return was === "false" && now === "true" && STRICT_FLAG_KEY.test(keyOf(path));
};

/** True when a list that is `was` has the entries of `now`, in the same order if a `!` entry makes the order matter. */
const sameEntries = (was: string[], now: string[]): boolean =>
  was.length === now.length &&
  (was.some((e) => e.startsWith("!"))
    ? was.join("\n") === now.join("\n")
    : [...was].sort().join("\n") === [...now].sort().join("\n"));

/** What a change of the list at `path` takes, or undefined. A lost entry of an ignore list checks more. */
const listWeaker = (
  path: string,
  was: string[],
  now: string[],
): string | undefined => {
  const ignoring = path.split(".").some((p) => IGNORE_KEY.test(p));
  const left = [...now];
  let dropped = false;
  for (const entry of was) {
    const at = left.indexOf(entry);
    if (at !== -1) left.splice(at, 1);
    else if (ignoring) dropped = true;
    else return `It removes the entry \`${shown(entry)}\` from \`${path}\`.`;
  }
  if (left.length === 0)
    return dropped || sameEntries(was, now)
      ? undefined
      : `It moves entries of \`${path}\`, and the order can matter.`;
  const safe =
    GROWABLE_LIST_KEY.test(keyOf(path)) &&
    !ignoring &&
    !left.some((e) => NEGATED_ENTRY.test(e));
  return safe
    ? undefined
    : `It adds the entry \`${shown(left[0] as string)}\` to \`${path}\`.`;
};

/** What a new key `path` with the value `value` does to a check: it asks unless the value is the strictest. */
const addedWeaker = (
  path: string,
  value: string | string[],
): string | undefined => {
  const segments = path.split(".");
  const plain = !segments.some((p) => IGNORE_KEY.test(p));
  const ok = Array.isArray(value)
    ? GROWABLE_LIST_KEY.test(keyOf(path)) &&
      plain &&
      !value.some((e) => NEGATED_ENTRY.test(e))
    : plain &&
      (value.toLowerCase() === "error" ||
        (value === "true" && STRICT_FLAG_KEY.test(keyOf(path))) ||
        (segments.some((p) => THRESHOLD_KEY.test(p)) &&
          (number(value) ?? 0) > 0));
  return ok
    ? undefined
    : `It adds the key \`${path}\`, which is not a stricter check.`;
};

/** What the change from `was` to `now` takes from a config, or undefined. */
const compare = (was: Conf, now: Conf): string | undefined => {
  for (const [path, before] of was) {
    const after = now.get(path);
    if (after === undefined) return `It removes the key \`${path}\`.`;
    if (Array.isArray(before) && Array.isArray(after)) {
      const found = listWeaker(path, before, after);
      if (found) return found;
    } else if (typeof before === "string" && typeof after === "string") {
      if (before !== after && !stricter(path, before, after))
        return `It changes \`${path}\` from \`${shown(before)}\` to \`${shown(after)}\`.`;
    } else return `It changes the kind of the value \`${path}\`.`;
  }
  for (const [path, after] of now) {
    if (was.has(path)) continue;
    const found = addedWeaker(path, after);
    if (found) return found;
  }
  return undefined;
};

/** The map of a config text by its file name, or undefined when the format is not readable. */
const readConf = (name: string, text: string): Conf | undefined => {
  if (text.trim() === "") return new Map();
  if (/\.toml$/.test(name))
    return sectionConf(
      text,
      false,
      name === "pyproject.toml" ? (s) => PYPROJECT_SECTIONS.test(s) : undefined,
    );
  if (INI_CONFIG_FILE.test(name))
    return sectionConf(
      text,
      true,
      name === "setup.cfg" ? (s) => SETUP_CFG_SECTIONS.test(s) : undefined,
    );
  if (/\.ya?ml$/.test(name)) return yamlConf(text);
  return (
    jsonConf(text) ?? (/\.jsonc?$/.test(name) ? undefined : yamlConf(text))
  );
};

/** What a call takes from a lint config, a runner config, or `tsconfig.json` at `rel`, or undefined. */
export const configWeaker = (
  rel: string,
  before: string,
  after: string,
): string | undefined => {
  const name = rel.split("/").at(-1) as string;
  if (before.trim() === "") return undefined;
  if (CODE_CONFIG_FILE.test(name)) return codeWeaker(before, after);
  const [was, now] = [readConf(name, before), readConf(name, after)];
  return was && now ? compare(was, now) : UNREADABLE;
};
